n1=json.loads((out/'node1-platform-profile.json').read_text());n2=json.loads((out/'node2-platform-profile.json').read_text());pol=json.loads((out/'platform-security-policy.json').read_text());write_json(out/'platform-validation-summary.json',evaluate_profiles(n1,n2,pol))
