names=['platform-security-policy.json','m21-control-mapping.json','threat-model.json','key-management-policy.json','measured-boot-policy.json','pag-platform-demo.service','apparmor-profile','selinux-policy.te','node1-platform-profile.json','node2-platform-profile.json','platform-validation-summary.json','firmware.bin','firmware-descriptor.json','firmware-descriptor.json.sig','rollback-positive.json','rollback-negative.json','dice-demo.json','signing-public.pem']
