man={'version':'0.21.0','milestone':'M21','purpose':'Embedded Linux & Platform Security Validation','m20_commit':head,'artifacts':{n:sha256_file(out/n) for n in names},'boundaries':pol['boundaries']};write_json(out/'m21-platform-manifest.json',man);sign_blob(out/'m21-platform-manifest.json',out/'signing-private.pem',out/'m21-platform-manifest.json.sig');secure_tree(out);print(f'PASS: M21 platform-security material generated at {out}');print(f"PASS: validation_mode={json.loads((out/'platform-validation-summary.json').read_text())['validation_mode']}")
